package io.github.diodeme.ji.agent;

import io.github.diodeme.ji.ai.ModelProvider;
import io.github.diodeme.ji.session.SessionStore;
import java.time.Clock;
import java.util.ArrayList;
import java.util.List;
import java.util.ServiceLoader;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** Framework-free explicit builder for the embedded Agent runtime. */
public final class AgentRuntimeBuilder {
    private ModelProvider provider;
    private SessionStore sessionStore;
    private final List<ToolDefinition> tools = new ArrayList<>();
    private PermissionDecider permissionDecider = request -> java.util.concurrent.CompletableFuture.completedFuture(PermissionDecider.Decision.DENY);
    private RuntimeConfiguration.IdGenerator idGenerator = scope -> scope + "-" + UUID.randomUUID();
    private Clock clock = Clock.systemUTC();
    private ExecutorService executor;

    public AgentRuntimeBuilder provider(ModelProvider value) { provider = value; return this; }
    public AgentRuntimeBuilder sessionStore(SessionStore value) { sessionStore = value; return this; }
    public AgentRuntimeBuilder tool(ToolDefinition value) { tools.add(value); return this; }
    public AgentRuntimeBuilder permissionDecider(PermissionDecider value) { permissionDecider = value; return this; }
    public AgentRuntimeBuilder idGenerator(RuntimeConfiguration.IdGenerator value) { idGenerator = value; return this; }
    public AgentRuntimeBuilder clock(Clock value) { clock = value; return this; }
    public AgentRuntimeBuilder executor(ExecutorService value) { executor = value; return this; }

    public AgentRuntime build() {
        if (provider == null) throw new IllegalStateException("provider is required");
        if (sessionStore == null) throw new IllegalStateException("sessionStore is required");
        var names = new java.util.HashSet<String>();
        for (ToolDefinition tool : tools) {
            if (!names.add(tool.schema().name())) throw new IllegalStateException("duplicate tool: " + tool.schema().name());
        }
        boolean ownsExecutor = executor == null;
        ExecutorService resolvedExecutor = ownsExecutor ? Executors.newThreadPerTaskExecutor(Thread.ofVirtual().name("ji-agent-", 0).factory()) : executor;
        var configuration = new RuntimeConfiguration(provider, sessionStore, tools, permissionDecider,
                idGenerator, clock, resolvedExecutor);
        AgentRuntimeFactory factory = ServiceLoader.load(AgentRuntimeFactory.class)
                .findFirst().orElseThrow(() -> new IllegalStateException("ji-agent-core is missing from the runtime classpath"));
        return factory.create(configuration, ownsExecutor);
    }

    /** Internal ServiceLoader seam that keeps implementation types out of the public builder. */
    public interface AgentRuntimeFactory {
        AgentRuntime create(RuntimeConfiguration configuration, boolean ownsExecutor);
    }
}
